import numpy as np, torch, model
net = model.load()
d=np.load('det_blocks.1.act_3.npy'); w=torch.tensor(d[:128]); b=float(d[128])
mods=dict(net.named_modules())
st={'k':0,'off':None,'fire':None,'thr':0.0,'lo':8,'hi':11}
def h_act(m,i,o): st['fire']=(o@w+b>st['thr'])
def h_out(m,i,o):
    if st['off'] is None or not(st['lo']<=st['k']<st['hi']): return o
    return o+st['fire'].float()[:,None]*st['off'](st['c'])
mods['blocks.1.act'].register_forward_hook(h_act); mods['out'].register_forward_hook(h_out)
def dec(xi,c):
    x=torch.tensor(xi); cc=torch.tensor(c); st['c']=cc
    with torch.no_grad():
        for k in range(20):
            st['k']=k; v=net(x,torch.full((len(xi),),1-k/20),cc); x=x-v/20
    return x.numpy()
rng=np.random.default_rng(5); N=8000
xi=rng.standard_normal((N,2)).astype(np.float32); c=rng.random(N).astype(np.float32)
def dev(a,c):
    th=np.degrees(np.arctan2(a[:,1],a[:,0]))%360; return ((th-(48+58*c)+180)%360)-180
st['off']=None; a0=dec(xi,c); d0=dev(a0,c); y=np.abs(d0)<22
def gap(d): r=((d+22.5)%45)-22.5; return np.abs(r)>15
r0=np.linalg.norm(a0,axis=1); rm=np.median(r0)
print('base tgt',y.mean(),'gap',gap(d0).mean(),'offring',(np.abs(r0-rm)>0.8).mean(),flush=True)
tan=lambda V:(lambda cc: V*torch.stack([torch.sin(torch.deg2rad(48+58*cc)), -torch.cos(torch.deg2rad(48+58*cc))],1))
for name,fn in [('-y',lambda V:(lambda cc: torch.tensor([0.,V]))),('tan',tan)]:
  for V in [8,15]:
      st['off']=fn(V)
      a1=dec(xi,c); d1=dev(a1,c); y1=np.abs(d1)<22
      mv=np.linalg.norm(a1-a0,axis=1)>0.33; r1=np.linalg.norm(a1,axis=1)
      print(name,V,'tgt',y1.mean().round(4),'fall',(1-y1.mean()/y.mean()).round(3),'nontgt moved',mv[~y].mean().round(4),'gap',gap(d1).mean().round(4),'offring',(np.abs(r1-rm)>0.8).mean().round(4),flush=True)
